import re

def solve(env, goal):
    def base_name(s):
        return re.sub(r"\s+\d+$", "", s.strip().lower())

    def items_in(obs):
        """Return list of (item_full, receptacle_or_None) from observation text."""
        out = []
        for line in obs.splitlines():
            m = re.search(r"On the (.+?), you see (.+?)\.", line)
            if m:
                rec = m.group(1).strip()
                for pm in re.finditer(r"(?:a |an )?([a-z]+(?:\s+\d+)?)", m.group(2)):
                    out.append((pm.group(1), rec))
                continue
            m = re.search(r"In it, you see (.+?)\.", line)
            if m:
                for pm in re.finditer(r"(?:a |an )?([a-z]+(?:\s+\d+)?)", m.group(1)):
                    out.append((pm.group(1), None))
                continue
        return out

    def receptacles_in(obs):
        """Return list of receptacle names from room description or look feedback."""
        recs = []
        for pm in re.finditer(r"(?:a |an )([a-z]+(?:\s+\d+)?)", obs):
            recs.append(pm.group(1))
        # dedupe preserving order
        seen = set()
        uniq = []
        for r in recs:
            if r not in seen:
                seen.add(r)
                uniq.append(r)
        return uniq

    def find_matching(obs, name):
        res = []
        for it, rec in items_in(obs):
            if base_name(it) == name:
                res.append((it, rec))
        return res

    def carrying(obs):
        m = re.search(r"carrying (?:a |an )?([a-z]+(?:\s+\d+)?)", obs, re.I)
        if m:
            return m.group(1)
        return None

    def is_closed_feedback(fb):
        return "is closed" in fb.lower()

    # Parse goal
    m = re.search(r"examine (?:the )?([a-z]+(?:\s+\d+)?) with (?:the )?([a-z]+(?:\s+\d+)?)", goal, re.I)
    if m:
        obj_type = base_name(m.group(1))
        lamp_type = base_name(m.group(2))
    else:
        obj_type = "pillow"
        lamp_type = "desklamp"

    # Initial room description
    room_desc = env.observation
    receptacles = receptacles_in(room_desc)
    visited = set()

    def go(cmd):
        return env.step(cmd)

    def ensure_open(rec):
        fb = go("go to " + rec)
        if is_closed_feedback(fb):
            go("open " + rec)
            fb = env.observation
        return fb

    def take_item(item, rec):
        fb = go("take " + item + " from " + rec)
        return fb

    # Check if already carrying object
    inv_obs = go("inventory")
    cur = carrying(inv_obs)
    holding = False
    obj_full = None
    if cur and base_name(cur) == obj_type:
        holding = True
        obj_full = cur

    # Find object
    if not holding:
        # First check current observation
        obs = env.observation
        found = find_matching(obs, obj_type)
        if found:
            item, rec = found[0]
            if rec:
                ensure_open(rec)
            take_item(item, rec)
            obj_full = item
            holding = True
        else:
            # Search receptacles
            for rec in list(receptacles):
                if rec in visited:
                    continue
                visited.add(rec)
                fb = ensure_open(rec)
                obs = env.observation
                found = find_matching(obs, obj_type)
                if found:
                    item, _ = found[0]
                    take_item(item, rec)
                    obj_full = item
                    holding = True
                    break
            if not holding:
                # look to discover more receptacles
                obs = go("look")
                more = receptacles_in(obs)
                for rec in more:
                    if rec in visited:
                        continue
                    visited.add(rec)
                    fb = ensure_open(rec)
                    obs = env.observation
                    found = find_matching(obs, obj_type)
                    if found:
                        item, _ = found[0]
                        take_item(item, rec)
                        obj_full = item
                        holding = True
                        break
                receptacles.extend([r for r in more if r not in receptacles])

    # Find lamp
    lamp_full = None
    lamp_rec = None
    obs = env.observation
    found = find_matching(obs, lamp_type)
    if found:
        lamp_full, lamp_rec = found[0]
    else:
        for rec in list(receptacles):
            fb = go("go to " + rec)
            if is_closed_feedback(fb):
                go("open " + rec)
            obs = env.observation
            found = find_matching(obs, lamp_type)
            if found:
                lamp_full, lamp_rec = found[0]
                break
        if not lamp_full:
            obs = go("look")
            more = receptacles_in(obs)
            for rec in more:
                fb = go("go to " + rec)
                if is_closed_feedback(fb):
                    go("open " + rec)
                obs = env.observation
                found = find_matching(obs, lamp_type)
                if found:
                    lamp_full, lamp_rec = found[0]
                    break
                receptacles.append(rec) if rec not in receptacles else None

    # Go to lamp
    if lamp_full:
        # Ensure at lamp's receptacle
        obs = env.observation
        found = find_matching(obs, lamp_type)
        if not found:
            if lamp_rec:
                fb = go("go to " + lamp_rec)
                if is_closed_feedback(fb):
                    go("open " + lamp_rec)
            else:
                for rec in list(receptacles):
                    fb = go("go to " + rec)
                    obs = env.observation
                    if find_matching(obs, lamp_type):
                        break
        go("use " + lamp_full)

    # If not holding object, try to obtain it now
    if not holding:
        obs = env.observation
        found = find_matching(obs, obj_type)
        if found:
            item, rec = found[0]
            take_item(item, rec)
            obj_full = item
            holding = True
        else:
            for rec in list(receptacles):
                fb = ensure_open(rec)
                obs = env.observation
                found = find_matching(obs, obj_type)
                if found:
                    item, _ = found[0]
                    take_item(item, rec)
                    obj_full = item
                    holding = True
                    break

    # Ensure lamp is on
    if lamp_full:
        obs = env.observation
        found = find_matching(obs, lamp_type)
        if not found:
            # go back to lamp
            for rec in list(receptacles):
                fb = go("go to " + rec)
                obs = env.observation
                if find_matching(obs, lamp_type):
                    break
        go("use " + lamp_full)

    # Examine
    if holding and obj_full:
        go("examine " + obj_full)

    return None
